  "bibleAlignment.aligned": {"forms":{"one":"An daidaita aya {count} na wannan littafi da Girkanci.","other":"An daidaita ayoyi {count} na wannan littafi da Girkanci."},"countVar":"count"},
  "bibleAlignment.stale": {"forms":{"one":"Aya {count} ta canza bayan an daidaita ta. Kalmominta ba su da haske har sai kun sake daidaita.","other":"Ayoyi {count} sun canza bayan an daidaita su. Kalmominsu ba su da haske har sai kun sake daidaita."},"countVar":"count"},
  "bibleAlignment.dotted": "Hasken da aka yi da ɗigo kusan ne: daidaita ba ya da tabbaci ga waɗannan kalmomi.",
  "bibleAlignment.shortBook": "Wannan littafi yana da ayoyi ƙasa da {min} da za a koya daga su, don haka kowane haske kusan ne (ɗigo).",
  "bibleAlignment.failed.offline": "An kasa daidaita rubutun asali: kuna ba tare da layi ba.",
  "bibleAlignment.failed.forbidden": "Mai kula da aiki kawai zai iya daidaita rubutun asali.",
  "bibleAlignment.failed.failed": "An kasa daidaita rubutun asali.",
  "bibleChecks.n1.name": "An kiyaye lamba",
  "bibleChecks.n1.description": "Inda asali ya faɗi lamba, fassara tana da ita ma, a matsayin lambobi ko kalmar lamba daga Bayanin harshe.",
  "bibleChecks.n2.name": "An kiyaye lambar jerin",
  "bibleChecks.n2.description": "Inda asali ya ce “the third day” ko “the sixth hour”, fassara da ke rubuta lambobi da lambobi tana da lamba iri ɗaya.",
  "bibleChecks.m3.description": "Inda asali ya ce “not” ko “never”, fassara tana da ɗaya daga cikin kalmomin musun daga Bayanin harshe.",
  "bibleChecks.s1.name": "Kan ga kowane sashe",
  "bibleChecks.s1.description": "Kowane sashe yana farawa da kan sashe, kuma babu kan da ke tsaye a cikin sashe. Yana gudana a Ku duba fayil.",
  "bibleChecks.s3.name": "Jumla tana ci gaba",
  "bibleChecks.s3.description": "Inda jumlar asali ke ci gaba zuwa aya ta gaba, fassara ba ta ƙare da jumlarta a ƙarshen aya ba.",
  "bibleChecks.s6.name": "Ayoyin da tsoffin rubutun hannu ba su da su",
  "bibleChecks.s6.description": "Ayoyi kamar Matthew 17:21, waɗanda tsoffin rubutun hannu suka bar, suna bin Bayanin harshe: an bar su, a cikin ƙugiya ko a bayani na ƙasa.",
  "bibleChecks.s7.name": "Sassan da ake jayayya",
  "bibleChecks.s7.description": "John 7:53–8:11 da Mark 16:9–20 suna bin Bayanin harshe: an bar su, a cikin ƙugiya ko tare da bayani na ƙasa.",
  "bibleChecks.s8.name": "Lambar aya",
  "bibleChecks.s8.description": "Fayil yana da ƙwaya ga kowace aya da bayanan Nassi ke da ita, kuma babu wadda ba ta da ita, don haka gaskiyarsa ta isa ƙwayoyin da suka dace. Yana gudana a Ku duba fayil.",
  "bibleChecks.needs.numberWords": "Yana buƙata: kalmomin lamba a Bayanin harshe",
  "bibleChecks.needs.negators": "Yana buƙata: kalmomin musun a Bayanin harshe",
  "bibleChecks.needs.headings": "Yana buƙata: kanunai na sashe a Bayanin harshe",
  "bibleChecks.needs.textualVariants": "Yana buƙata: bambance-bambancen rubutu a Bayanin harshe",
  "bibleChecks.reason.numberMissing": "Asali yana da lamba {value} a wannan aya, amma fassara ba ta da lambobinta ko kalmar lambarta.",
  "bibleChecks.reason.numberMissingDigitsOnly": "Asali yana da lamba {value} a wannan aya, amma fassara ba ta da lambobi gare ta. Tare da kalmomin lamba na al'ada, wannan duba yana karanta lambobi kawai. Don duba lambobi da aka rubuta a matsayin kalmomi, ku shigar da kalmomin lambarku a Bayanin harshe.",
  "bibleChecks.reason.numberMissingUnlisted": "Asali yana da lamba {value} a wannan aya. Fassara ba ta da lambobi gare ta, kuma Bayanin harshe ba shi da kalma gare ta. Idan fassararku tana rubuta ta a matsayin kalma, ku ƙara kalmar zuwa Kalmomin lamba.",
  "bibleChecks.reason.ordinalMissing": "Asali yana da lambar jerin {value} a wannan aya, kamar “the third day”. Fassara tana rubuta lambobi da lambobi amma ba ta da wannan.",
  "bibleChecks.reason.negationMissing": "Asali yana yin magana ta musun a wannan aya, amma fassara ba ta da ɗaya daga cikin kalmomin musun daga Bayanin harshe. Ba tare da ɗaya ba, ma'ana na iya zama akasin.",
  "bibleChecks.reason.negationFewer": "Fassara tana da ƙarancin kalmomin musun ({found}) fiye da musun da asali ke da su ({expected}) a wannan aya.",
  "bibleChecks.reason.sentenceEndsEarly": "Jumlar asali tana ci gaba zuwa aya ta gaba, amma fassara tana ƙare da jumlarta a nan. Ku duba cewa ayoyi biyu har yanzu suna karantawa a matsayin tunani ɗaya.",
  "bibleChecks.reason.variantNotOmitted": "Bayanin harshe ya ce a bar ayoyin da tsoffin rubutun hannu ba su da su, amma wannan ƙwaya tana da rubutu ga {passage}.",
  "bibleChecks.reason.variantNotBracketed": "Bayanin harshe ya ce a kiyaye {passage} a cikin ƙugiya, amma wannan ƙwaya ba ta da ƙugiya.",
  "bibleChecks.reason.variantNoFootnote": "Bayanin harshe ya ce a ba {passage} bayani na ƙasa, amma wannan ƙwaya ba ta da bayani na ƙasa.",
  "bibleChecks.reason.headingMissing": "Sashe yana farawa a nan (“{title}”), amma babu kan sashe da ke gabansa.",
  "bibleChecks.reason.headingInsidePericope": "Wannan kan yana tsaye a cikin sashe (“{title}”), ba inda sashe yake farawa ba.",
  "bibleChecks.reason.verseNotInPack": "Bayanan Nassi ba su da aya {refs}, don haka gaskiyarsu ba ta isa wannan ƙwaya. Fayil zai iya lissafa ayoyi ta wata hanya.",
  "bibleChecks.reason.packVerseWithoutCell": "Bayanan Nassi suna da {refs} bayan wannan ƙwaya, amma fayil ba shi da ƙwaya gare ta. Fayil zai iya lissafa ayoyi ta wata hanya.",
