  "bibleHelps.voices.disputed": "Ana jayayya da iyaka",
  "bibleParticipants.p1.name": "An kiyaye sunaye",
  "bibleParticipants.p1.description": "Inda asali ya ambaci wani, fassara tana da sunan da aka amince: yanke shawara kamar render.person.Peter, ko shigar kalma.",
  "bibleParticipants.p2.name": "Suna ɗaya a duk fayil",
  "bibleParticipants.p2.description": "Kowane mutum, rukuni ko wuri yana da suna ɗaya a kowace aya da ke amfani da sigar suna iri ɗaya a asali. Yana gudana a Ku duba fayil.",
  "bibleParticipants.p3.name": "An raba masu suna ɗaya",
  "bibleParticipants.p3.description": "Inda asali ya ambaci ɗaya daga cikin mutane da yawa masu suna ɗaya (Maryamu shida, Siman tara), fassara tana amfani da sunan wannan mutum, ba na mai suna ɗaya ba.",
  "bibleParticipants.p4.name": "An kiyaye sigar suna",
  "bibleParticipants.p4.description": "Inda asali ya yi amfani da sigar suna ɗaya (Cephas, ba Simon ba) kuma aiki yana da suna ga kowace siga, fassara tana amfani da sunan wannan siga.",
  "bibleParticipants.p5.name": "Babu sunayen da asali ba shi da su",
  "bibleParticipants.p5.description": "Fassara ba ta ambaci wanda asalin aya bai ambata ba, da suna, a matsayin wakili ko a matsayin batu na fi'ili. Batun aya ta gaba ko ta baya ma yana ƙidaya.",
  "bibleParticipants.p6.name": "An ambaci batu da ba a faɗi ba daidai",
  "bibleParticipants.p6.description": "Inda asali bai ambaci kowa ba kuma ya nuna wanda ke aiki kawai (“he says”), suna da fassara ta ƙara shine sunan wannan mutum.",
  "bibleParticipants.p8.description": "Inda kowane “you” a asali ke magana da mutum ɗaya, ko kowane ɗaya ke magana da mutane da yawa, fassara tana amfani da “you” na wannan lamba daga Bayanin harshe, kuma babu na ɗayan.",
  "bibleParticipants.p9.name": "“we” da ke haɗa ko barin",
  "bibleParticipants.p9.description": "Inda “we” ya haɗa mutanen da ake magana da su, ko ya bar su, fassara tana amfani da “we” na haɗawa ko na barin daga Bayanin harshe.",
  "bibleParticipants.p10.name": "Sigogin biyu, uku da kaɗan",
  "bibleParticipants.p10.description": "Inda wakili ke nufin mutane biyu, uku ko kaɗan, fassara tana amfani da sigar wannan lamba daga Bayanin harshe.",
  "bibleParticipants.p14.name": "Lord da Spirit",
  "bibleParticipants.p14.description": "Inda κύριος ke nufin Yesu ko Allah, ko πνεῦμα ke nufin Ruhun Mai Tsarki, fassara tana amfani da fassarar aiki ga kowanne.",
  "bibleParticipants.p15.name": "Manyan haruffa ga Allah",
  "bibleParticipants.p15.description": "Inda salo na gida ke yin manyan haruffa ga wakilan Allah, Yesu da Ruhun Mai Tsarki, waɗannan wakilai suna farawa da babban harafi.",
  "bibleParticipants.x3.name": "Maganga da aka maimaita iri ɗaya",
  "bibleParticipants.x3.description": "Inda asali ya maimaita maganga a fayil, fassara tana fassara ta iri ɗaya kowane lokaci. Yana gudana a Ku duba fayil.",
  "bibleParticipants.x4.name": "An kiyaye yanke shawara",
  "bibleParticipants.x4.description": "Inda aiki ya yanke shawarar ko “we” a sashe yana haɗa mai sauraro (yanke shawara na clusivity), kowane “we” a wannan sashe yana amfani da sigar da aka yanke.",
  "bibleParticipants.needs.agreedNames": "Yana buƙata: sunayen da aka amince, daga yanke shawara (render.…) ko shigar kalma",
  "bibleParticipants.needs.nameForms": "Yana buƙata: yanke shawara ga sigogi biyu na suna ɗaya (render.….form.…)",
  "bibleParticipants.needs.secondPersonForms": "Yana buƙata: sigogin “you” na ɗaya da jam'i a Bayanin harshe",
  "bibleParticipants.needs.secondPersonSame": "Ba a amfani ba: a Bayanin harshe, “you” iri ɗaya ne ga mutum ɗaya da ga da yawa",
  "bibleParticipants.needs.clusivityForms": "Yana buƙata: sigogin “we” na haɗawa da na barin a Bayanin harshe",
  "bibleParticipants.needs.clusivitySame": "Ba a amfani ba: a Bayanin harshe, “we” iri ɗaya ne tare da mai sauraro ko ba tare da shi ba",
  "bibleParticipants.needs.groupNumberForms": "Yana buƙata: sigogin biyu, uku ko kaɗan a Bayanin harshe",
  "bibleParticipants.needs.groupNumberNone": "Ba a amfani ba: Bayanin harshe ba shi da biyu, uku ko kaɗan",
  "bibleParticipants.needs.divineNames": "Yana buƙata: fassarar κύριος a Bayanin harshe (Sunayen Allah) ko a matsayin yanke shawara",
  "bibleParticipants.needs.deityCapitals": "Yana buƙata: ƙa'idar manyan haruffa ga Allah a Bayanin harshe (Sunayen Allah)",
  "bibleParticipants.needs.deityCapitalsOff": "Ba a amfani ba: salo na gida yana kiyaye wakilan Allah da ƙananan haruffa",
  "bibleParticipants.needs.alignment": "Yana buƙata: daidaita kalma tsakanin Girkanci da fassara, wanda wannan aiki ba shi da shi",
  "bibleParticipants.needs.clusivityDecisions": "Yana buƙata: yanke shawara game da “we” a sashe (clusivity.…)",
  "bibleParticipants.reason.nameMissing": "Asali yana ambaton {name} a nan, amma fassara ba ta da ɗaya daga cikin sunayen da aka amince ({renderings}).",
  "bibleParticipants.reason.nameMissingPronoun": "Asali yana ambaton {name} a nan, amma fassara ba ta da ɗaya daga cikin sunayen da aka amince ({renderings}). Wakili na iya zama daidai a nan, saboda mahalli ya riga ya ambaci wannan mutum.",
